#include <bits/stdc++.h>@using namespace std;@#define pb push_back@typedef long long ll;@class Solution {@public:@    int largestRectangleArea(vector<int>& h) {@        int n = h.size();@        stack<int> s;@        int mx = 0;@        for(int i=0;i<=n;i++) {@            while(!s.empty() && (i==n || h[s.top()]>=h[i])) {@                int v = h[s.top()];@                s.pop();@                int w = s.empty() ? i : i-s.top()-1;@                mx = max(mx, v*w);@            }@            s.push(i);@        }@        return mx;@    }@    int maximalRectangle(vector<vector<char>>& mat) {@        int n = mat.size();@        if(n==0) return 0;@        int m = mat[0].size();@        vector<int> h(m, 0);@        int ans = 0;@        for(int i=0;i<n;i++) {@            for(int j=0;j<m;j++) {@                if(mat[i][j]=='1') h[j]++;@                else h[j]=0;@            }@            ans = max(ans, largestRectangleArea(h));@        }@        return ans;@    }@};
